// src/pages/FarmMap.jsx
import { useRef, useState, useEffect, useCallback } from "react";
import C from "../constants/colors";
import S from "../utils/storage";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import Input from "../components/ui/Input";
import Btn from "../components/ui/Btn";

const CROP_OPTIONS = [
  "Tomato","Rice","Wheat","Maize","Cotton","Onion","Potato","Brinjal","Okra",
  "Groundnut","Sugarcane","Turmeric","Banana","Mango","Coconut","Ragi","Bajra",
  "Toor Dal","Urad Dal","Moong Dal","Sesame","Green Chilli","Carrot","Cauliflower",
];
const SOIL_TYPES    = ["Red","Black","Loamy","Sandy","Clay","Alluvial"];
const FARM_STATUSES = ["Healthy","Disease Alert","Monitor","Harvested","Fallow"];

// ── Tile layers ───────────────────────────────────────────────────────────────
const TILE_LAYERS = {
  street: {
    url: "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
    attribution: "© OpenStreetMap contributors",
    label: "🗺️ Map",
  },
  satellite: {
    url: "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",
    attribution: "© Esri, Maxar, Earthstar Geographics",
    label: "🛰️ Satellite",
  },
};

function FarmMap({ user, t }) {
  const mapRef         = useRef(null);
  const mapInstance    = useRef(null);
  const tileLayerRef   = useRef(null);
  const placePinRef    = useRef(null);   // draggable placement marker
  const searchTimerRef = useRef(null);
  const farmMarkersRef = useRef({});     // { [farm.id]: leafletMarker }

  const [loaded,        setLoaded]        = useState(false);
  const [farms,         setFarms]         = useState(() => Array.isArray(user?.farms) ? user.farms : []);
  const [addMode,       setAddMode]       = useState(false);
  const [confirmRemove, setConfirmRemove] = useState(null); // farm id pending confirmation
  const [tileMode,    setTileMode]    = useState("street");
  const [gpsStatus,   setGpsStatus]   = useState("idle"); // idle | loading | done | error
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [searching,   setSearching]   = useState(false);
  const [pinCoords,   setPinCoords]   = useState(null);   // { lat, lon }

  const [formFarm, setFormFarm] = useState({
    name: "", crop: CROP_OPTIONS[0], size: "", soilType: "Red", status: "Healthy",
  });

  // ── Translations ────────────────────────────────────────────────────────────
  const TX = {
    title:       t?.("map.title")           || "Farm Map",
    subtitle:    t?.("map.subtitle")        || "GPS mapping of your farm plots",
    addPlot:     t?.("map.addPlot")         || "+ Add Farm",
    yourFarms:   t?.("map.yourFarms")       || "My Farm Plots",
    noFarms:     t?.("map.noFarms")         || "No farms added yet",
    addFirst:    t?.("map.addFirst")        || "Click '+ Add Farm' to start",
    area:        t?.("map.area")            || "Area",
    crop:        t?.("map.crop")            || "Crop",
    plotName:    t?.("map.plotName")        || "Plot Name",
    loading:     t?.("common.loading")      || "Loading map…",
    saveFarm:    t?.("save")                || "Save Farm",
    cancel:      t?.("cancel")             || "Cancel",
    acres:       t?.("common.acres")        || "acres",
    fieldConds:  "🌡️ Field Conditions Today",
    temp:        "Temperature",
    humidity:    t?.("dashboard.weatherLabel")    || "Humidity",
    pestRisk:    t?.("dashboard.pestAlert")       || "Pest Risk",
    diseaseRisk: t?.("dashboard.diseasePressure") || "Disease Risk",
    irrigation:  "Irrigation Need",
    ndvi:        "📡 NDVI Satellite Status",
    soilType:    "Soil Type",
    status:      "Status",
  };

  // ── Load Leaflet ────────────────────────────────────────────────────────────
  useEffect(() => {
    if (document.querySelector("#leaflet-css")) {
      if (window.L) setLoaded(true);
      else {
        const wait = setInterval(() => { if (window.L) { setLoaded(true); clearInterval(wait); } }, 100);
        return () => clearInterval(wait);
      }
      return;
    }
    const css   = document.createElement("link");
    css.id      = "leaflet-css";
    css.rel     = "stylesheet";
    css.href    = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
    document.head.appendChild(css);

    const script   = document.createElement("script");
    script.src     = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";
    script.onload  = () => setLoaded(true);
    script.onerror = () => console.warn("Leaflet failed to load");
    document.head.appendChild(script);
  }, []);

  // ── Init map ────────────────────────────────────────────────────────────────
  useEffect(() => {
    if (!loaded || !mapRef.current || mapInstance.current) return;
    const L   = window.L;
    if (!L) return;

    const lat = user?.lat || 9.9252;
    const lon = user?.lon || 78.1198;

    const map = L.map(mapRef.current, { zoomControl: true }).setView([lat, lon], 14);

    // Default tile layer
    tileLayerRef.current = L.tileLayer(TILE_LAYERS.street.url, {
      attribution: TILE_LAYERS.street.attribution,
      maxZoom: 21,
    }).addTo(map);

    // User location marker
    const userIcon = L.divIcon({
      html: `<div style="background:${C.bg2 || "#1a7a3a"};width:14px;height:14px;border-radius:50%;border:3px solid white;box-shadow:0 2px 8px rgba(0,0,0,0.5)"></div>`,
      iconSize: [20, 20], iconAnchor: [10, 10],
    });
    L.marker([lat, lon], { icon: userIcon })
      .addTo(map)
      .bindPopup(`<b>📍 ${user?.name || "Your Location"}</b><br>${user?.district || ""}`);

    // Existing farm markers
    farms.forEach(farm => { if (farm?.lat && farm?.lon) _addMarker(L, map, farm); });

    // Click → move placement pin
    map.on("click", e => {
      if (!addMode) return;
      movePlacePin(L, map, e.latlng.lat, e.latlng.lng);
    });

    mapInstance.current = map;
  }, [loaded]); // eslint-disable-line

  // ── Toggle tile layer ───────────────────────────────────────────────────────
  useEffect(() => {
    const map = mapInstance.current;
    const L   = window.L;
    if (!map || !L) return;

    if (tileLayerRef.current) { tileLayerRef.current.remove(); }
    const layer = TILE_LAYERS[tileMode];
    tileLayerRef.current = L.tileLayer(layer.url, {
      attribution: layer.attribution,
      maxZoom: 21,
    }).addTo(map);
  }, [tileMode]);

  // ── Placement pin helpers ───────────────────────────────────────────────────
  const movePlacePin = useCallback((L, map, lat, lon) => {
    const pinHtml = `
      <div style="position:relative;display:flex;flex-direction:column;align-items:center">
        <div style="background:#e05c00;color:#fff;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;white-space:nowrap;box-shadow:0 2px 8px rgba(0,0,0,0.4)">📌 Drop here</div>
        <div style="width:2px;height:12px;background:#e05c00"></div>
        <div style="width:8px;height:8px;border-radius:50%;background:#e05c00;margin-top:-2px"></div>
      </div>`;
    const pinIcon = L.divIcon({ html: pinHtml, className: "", iconAnchor: [40, 38] });

    if (placePinRef.current) {
      placePinRef.current.setLatLng([lat, lon]);
    } else {
      placePinRef.current = L.marker([lat, lon], { icon: pinIcon, draggable: true }).addTo(map);
      placePinRef.current.on("dragend", e => {
        const { lat: dlat, lng: dlon } = e.target.getLatLng();
        setPinCoords({ lat: dlat, lon: dlon });
      });
    }
    setPinCoords({ lat, lon });
  }, []);

  const removePlacePin = useCallback(() => {
    if (placePinRef.current) {
      placePinRef.current.remove();
      placePinRef.current = null;
    }
    setPinCoords(null);
  }, []);

  // ── Map click handler update when addMode changes ───────────────────────────
  useEffect(() => {
    const map = mapInstance.current;
    if (!map) return;
    if (!addMode) removePlacePin();
  }, [addMode, removePlacePin]);

  // ── GPS Locate ──────────────────────────────────────────────────────────────
  const handleGPS = () => {
    if (!navigator.geolocation) { setGpsStatus("error"); return; }
    setGpsStatus("loading");
    navigator.geolocation.getCurrentPosition(
      pos => {
        const { latitude: lat, longitude: lon, accuracy } = pos.coords;
        setGpsStatus("done");
        const map = mapInstance.current;
        const L   = window.L;
        if (map && L) {
          map.flyTo([lat, lon], 18, { animate: true, duration: 1.4 });
          movePlacePin(L, map, lat, lon);

          // Accuracy circle
          if (map._accuracyCircle) map._accuracyCircle.remove();
          map._accuracyCircle = L.circle([lat, lon], {
            radius: accuracy,
            color: "#1a7a3a", fillColor: "#1a7a3a", fillOpacity: 0.1, weight: 1.5,
          }).addTo(map).bindPopup(`📡 GPS Accuracy: ±${Math.round(accuracy)}m`).openPopup();
        }
        setTimeout(() => setGpsStatus("idle"), 3000);
      },
      err => {
        setGpsStatus("error");
        setTimeout(() => setGpsStatus("idle"), 3000);
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  // ── Nominatim Address Search ────────────────────────────────────────────────
  const handleSearch = query => {
    setSearchQuery(query);
    clearTimeout(searchTimerRef.current);
    if (query.length < 3) { setSearchResults([]); return; }
    setSearching(true);
    searchTimerRef.current = setTimeout(async () => {
      try {
        const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query + ", India")}&limit=5&addressdetails=1`;
        const res  = await fetch(url, { headers: { "Accept-Language": "en" } });
        const data = await res.json();
        setSearchResults(data);
      } catch { setSearchResults([]); }
      finally { setSearching(false); }
    }, 500);
  };

  const selectSearchResult = result => {
    const lat = parseFloat(result.lat);
    const lon = parseFloat(result.lon);
    const map = mapInstance.current;
    const L   = window.L;
    if (map && L) {
      map.flyTo([lat, lon], 17, { animate: true, duration: 1.2 });
      movePlacePin(L, map, lat, lon);
    }
    setSearchQuery(result.display_name.split(",")[0]);
    setSearchResults([]);
  };

  // ── Farm markers ────────────────────────────────────────────────────────────
  const _addMarker = (L, map, farm) => {
    const fc = farm.status === "Healthy" ? "#1a7a3a" : farm.status === "Disease Alert" ? "#b83232" : "#c87010";
    const fi = L.divIcon({
      html: `<div style="background:${fc};color:#fff;padding:4px 9px;border-radius:6px;font-size:11px;font-weight:600;white-space:nowrap;box-shadow:0 2px 8px rgba(0,0,0,0.35)">${farm.crop || ""}</div>`,
      className: "",
    });
    const marker = L.marker([farm.lat, farm.lon], { icon: fi })
      .addTo(map)
      .bindPopup(
        `<b>${farm.name}</b><br>` +
        `${TX.crop}: ${farm.crop}<br>` +
        `${TX.area}: ${farm.size} ${TX.acres}<br>` +
        `Status: ${farm.status}<br>` +
        `<span style="font-size:10px;color:#777">📍 ${farm.lat.toFixed(5)}, ${farm.lon.toFixed(5)}</span>`
      );
    farmMarkersRef.current[farm.id] = marker;
  };

  // ── Remove farm ─────────────────────────────────────────────────────────────
  const removeFarm = id => {
    // Remove marker from map
    const marker = farmMarkersRef.current[id];
    if (marker) { marker.remove(); delete farmMarkersRef.current[id]; }

    const updated = farms.filter(f => f.id !== id);
    setFarms(updated);
    setConfirmRemove(null);

    const users = S.get("users") || [];
    const idx   = users.findIndex(u => u.id === user?.id);
    if (idx >= 0) { users[idx].farms = updated; S.set("users", users); S.set("current_user", users[idx]); }
  };

  // ── Save farm ───────────────────────────────────────────────────────────────
  const saveFarm = () => {
    if (!formFarm.name || !formFarm.crop) return;

    // Priority: dragged pin > clicked pin > GPS default > user profile > Tamil Nadu centroid
    const lat = pinCoords?.lat ?? ((user?.lat || 9.9252) + (Math.random() - 0.5) * 0.02);
    const lon = pinCoords?.lon ?? ((user?.lon || 78.1198) + (Math.random() - 0.5) * 0.02);

    const farm = {
      id: Date.now(), ...formFarm, lat, lon,
      addedOn: new Date().toLocaleDateString("en-IN"),
    };
    const updated = [...farms, farm];
    setFarms(updated);

    const users = S.get("users") || [];
    const idx   = users.findIndex(u => u.id === user?.id);
    if (idx >= 0) { users[idx].farms = updated; S.set("users", users); S.set("current_user", users[idx]); }

    if (mapInstance.current && window.L) _addMarker(window.L, mapInstance.current, farm);
    removePlacePin();
    setAddMode(false);
    setSearchQuery("");
    setFormFarm({ name: "", crop: CROP_OPTIONS[0], size: "", soilType: "Red", status: "Healthy" });
  };

  // ── Helpers ─────────────────────────────────────────────────────────────────
  const statusColor = { Healthy: C.bg2, "Disease Alert": C.red, Monitor: C.orange };
  const statusBg    = { Healthy: C.pale, "Disease Alert": "#fff0f0", Monitor: "#fff8ee" };

  const fieldConditions = [
    { label: TX.temp,        val: "32°C",          risk: "Low"    },
    { label: TX.humidity,    val: "72%",            risk: "Medium" },
    { label: TX.pestRisk,    val: "Moderate",       risk: "Medium" },
    { label: TX.diseaseRisk, val: "High",           risk: "High"   },
    { label: TX.irrigation,  val: "Tomorrow 6 AM", risk: ""       },
  ];

  const gpsLabel = { idle: "📡 Use GPS", loading: "⏳ Locating…", done: "✅ Located!", error: "❌ GPS Failed" };
  const gpsColor = { idle: "#1a7a3a", loading: "#c87010", done: "#1a7a3a", error: "#b83232" };

  // ── Render ──────────────────────────────────────────────────────────────────
  return (
    <div style={{ padding: 20 }}>

      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 16 }}>
        <div>
          <h1 style={{ fontSize: 22, fontWeight: 600, color: C.text, margin: 0 }}>🗺️ {TX.title}</h1>
          <p style={{ color: C.muted, fontSize: 13, margin: "4px 0 0" }}>{TX.subtitle}</p>
        </div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          {/* Satellite toggle */}
          <button
            onClick={() => setTileMode(m => m === "street" ? "satellite" : "street")}
            style={{
              padding: "7px 14px", borderRadius: 8, border: `1px solid ${C.border || "#ddd"}`,
              background: tileMode === "satellite" ? "#1a1a2e" : "#fff",
              color: tileMode === "satellite" ? "#7dd87d" : C.text,
              fontSize: 12.5, fontWeight: 600, cursor: "pointer",
            }}
          >
            {TILE_LAYERS[tileMode === "satellite" ? "street" : "satellite"].label}
          </button>
          <Btn onClick={() => setAddMode(!addMode)} variant={addMode ? "amber" : "primary"}>
            {addMode ? "📌 Placing Pin…" : TX.addPlot}
          </Btn>
        </div>
      </div>

      {/* Add Farm Panel */}
      {addMode && (
        <Card style={{ marginBottom: 14, background: "#fffbeb", border: "1px solid #e0c060" }}>
          <div style={{ fontSize: 13, fontWeight: 700, color: "#a06000", marginBottom: 12 }}>
            📌 Add New Farm Plot
          </div>

          {/* ── Location row ── */}
          <div style={{ display: "flex", gap: 8, marginBottom: 12, alignItems: "flex-start", flexWrap: "wrap" }}>

            {/* GPS button */}
            <button
              onClick={handleGPS}
              disabled={gpsStatus === "loading"}
              style={{
                padding: "9px 14px", borderRadius: 8, border: "none",
                background: gpsColor[gpsStatus], color: "#fff",
                fontSize: 12.5, fontWeight: 600, cursor: gpsStatus === "loading" ? "wait" : "pointer",
                whiteSpace: "nowrap", flexShrink: 0,
              }}
            >
              {gpsLabel[gpsStatus]}
            </button>

            {/* Address search */}
            <div style={{ flex: 1, minWidth: 200, position: "relative" }}>
              <div style={{ position: "relative" }}>
                <input
                  value={searchQuery}
                  onChange={e => handleSearch(e.target.value)}
                  placeholder="🔍 Search village, town or landmark…"
                  style={{
                    width: "100%", padding: "9px 12px", borderRadius: 8,
                    border: `1px solid ${C.border || "#ddd"}`, fontSize: 13,
                    background: "#fff", boxSizing: "border-box",
                    outline: "none",
                  }}
                />
                {searching && (
                  <span style={{ position: "absolute", right: 10, top: "50%", transform: "translateY(-50%)", fontSize: 11, color: C.muted }}>
                    Searching…
                  </span>
                )}
              </div>
              {searchResults.length > 0 && (
                <div style={{
                  position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0, zIndex: 9999,
                  background: "#fff", borderRadius: 8, border: `1px solid ${C.border || "#ddd"}`,
                  boxShadow: "0 6px 20px rgba(0,0,0,0.15)", maxHeight: 200, overflowY: "auto",
                }}>
                  {searchResults.map((r, i) => (
                    <div
                      key={i}
                      onClick={() => selectSearchResult(r)}
                      style={{
                        padding: "9px 12px", cursor: "pointer", fontSize: 12.5,
                        borderBottom: i < searchResults.length - 1 ? `1px solid #f0f0f0` : "none",
                        lineHeight: 1.4,
                      }}
                      onMouseEnter={e => e.currentTarget.style.background = "#f7fdf7"}
                      onMouseLeave={e => e.currentTarget.style.background = "#fff"}
                    >
                      <span style={{ fontSize: 13 }}>📍 </span>
                      <b>{r.display_name.split(",")[0]}</b>
                      <span style={{ color: C.muted || "#888" }}>, {r.display_name.split(",").slice(1, 3).join(",")}</span>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Coords display */}
            {pinCoords && (
              <div style={{
                padding: "9px 12px", borderRadius: 8, background: "#e8f5e9",
                border: "1px solid #a5d6a7", fontSize: 11.5, color: "#2e7d32",
                fontFamily: "monospace", whiteSpace: "nowrap", flexShrink: 0,
              }}>
                📍 {pinCoords.lat.toFixed(5)}, {pinCoords.lon.toFixed(5)}
              </div>
            )}
          </div>

          {/* Instructions */}
          <div style={{
            padding: "8px 12px", borderRadius: 7, background: "#fff8e1",
            border: "1px solid #ffe082", fontSize: 12, color: "#7a5800", marginBottom: 12,
            display: "flex", gap: 8, alignItems: "flex-start",
          }}>
            <span style={{ fontSize: 16 }}>💡</span>
            <span>
              <b>3 ways to place your farm:</b>&nbsp;
              (1) Click <b>Use GPS</b> to snap to your device location &nbsp;·&nbsp;
              (2) <b>Search</b> a village or landmark &nbsp;·&nbsp;
              (3) <b>Click on the map</b> directly, then <b>drag the pin</b> to fine-tune
            </span>
          </div>

          {/* Form fields */}
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10 }}>
            <Input label={TX.plotName} value={formFarm.name}
              onChange={e => setFormFarm(p => ({ ...p, name: e.target.value }))}
              placeholder="e.g. North Field" />
            <Input label={TX.crop} value={formFarm.crop}
              onChange={e => setFormFarm(p => ({ ...p, crop: e.target.value }))}
              options={CROP_OPTIONS} />
            <Input label={`${TX.area} (${TX.acres})`} value={formFarm.size} type="number"
              onChange={e => setFormFarm(p => ({ ...p, size: e.target.value }))}
              placeholder="e.g. 2.5" />
            <Input label={TX.soilType} value={formFarm.soilType}
              onChange={e => setFormFarm(p => ({ ...p, soilType: e.target.value }))}
              options={SOIL_TYPES} />
            <Input label={TX.status} value={formFarm.status}
              onChange={e => setFormFarm(p => ({ ...p, status: e.target.value }))}
              options={FARM_STATUSES} />
          </div>

          <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
            <Btn onClick={saveFarm} style={{ padding: "8px 20px" }}>✅ {TX.saveFarm}</Btn>
            <Btn variant="ghost" onClick={() => { setAddMode(false); setSearchQuery(""); }} style={{ padding: "8px 20px" }}>{TX.cancel}</Btn>
          </div>
        </Card>
      )}

      {/* Map + Side Panel */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 300px", gap: 14 }}>

        <Card style={{ padding: 0, overflow: "hidden", position: "relative" }}>
          {!loaded && (
            <div style={{ height: 480, display: "flex", alignItems: "center", justifyContent: "center", color: C.muted }}>
              {TX.loading}
            </div>
          )}
          <div ref={mapRef} style={{ height: 480, display: loaded ? "block" : "none" }} />

          {/* Map overlay: tile toggle */}
          {loaded && (
            <div style={{ position: "absolute", bottom: 12, left: 12, zIndex: 999, display: "flex", gap: 6 }}>
              {Object.entries(TILE_LAYERS).map(([key, layer]) => (
                <button
                  key={key}
                  onClick={() => setTileMode(key)}
                  style={{
                    padding: "5px 10px", borderRadius: 6, fontSize: 11.5, fontWeight: 600,
                    border: "none", cursor: "pointer",
                    background: tileMode === key ? "#1a7a3a" : "rgba(255,255,255,0.9)",
                    color: tileMode === key ? "#fff" : "#333",
                    boxShadow: "0 2px 6px rgba(0,0,0,0.2)",
                  }}
                >
                  {layer.label}
                </button>
              ))}
            </div>
          )}
        </Card>

        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>

          {/* Farm list */}
          <Card style={{ padding: 12 }}>
            <div style={{ fontSize: 12.5, fontWeight: 600, color: C.text, marginBottom: 8 }}>
              {TX.yourFarms} ({farms.length})
            </div>
            {farms.length === 0 && (
              <div style={{ fontSize: 12, color: C.muted, textAlign: "center", padding: "16px 0" }}>
                {TX.noFarms}<br />{TX.addFirst}
              </div>
            )}
            {farms.map(f => (
              <div key={f.id} style={{ padding: "8px 0", borderBottom: `1px solid ${C.border}`, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <div>
                  <div style={{ fontSize: 13, fontWeight: 500, color: C.text }}>{f.name}</div>
                  <div style={{ fontSize: 11, color: C.muted }}>{f.crop} · {f.size} {TX.acres} · {f.soilType}</div>
                  <div style={{ fontSize: 10.5, color: "#aaa", fontFamily: "monospace" }}>
                    {f.lat?.toFixed(4)}, {f.lon?.toFixed(4)}
                  </div>
                </div>
                <Badge color={statusColor[f.status] || C.muted} bg={statusBg[f.status] || C.pale}>
                  {f.status}
                </Badge>
              </div>
            ))}
          </Card>

          {/* Field conditions */}
          <Card style={{ padding: 12, background: C.pale }}>
            <div style={{ fontSize: 12.5, fontWeight: 600, color: C.text, marginBottom: 8 }}>
              {TX.fieldConds}
            </div>
            {fieldConditions.map(r => (
              <div key={r.label} style={{ display: "flex", justifyContent: "space-between", marginBottom: 6, fontSize: 12.5 }}>
                <span style={{ color: C.muted }}>{r.label}</span>
                <span style={{ fontWeight: 500, color: r.risk === "High" ? C.red : r.risk === "Medium" ? C.orange : C.text }}>
                  {r.val}
                </span>
              </div>
            ))}
          </Card>

          {/* NDVI */}
          <Card style={{ padding: 12, background: "linear-gradient(135deg,#0e3a1c,#062010)", border: "none" }}>
            <div style={{ fontSize: 13, fontWeight: 600, color: "#fff", marginBottom: 6 }}>{TX.ndvi}</div>
            <div style={{ fontSize: 12, color: "rgba(255,255,255,0.7)", lineHeight: 1.6 }}>
              Crop health index: <span style={{ color: "#5de87a", fontWeight: 600 }}>0.72 (Good)</span><br />
              Last satellite pass: Today 10:32 AM<br />
              Cloud cover: 18%
            </div>
            <div style={{ marginTop: 10, display: "flex", gap: 6 }}>
              {[{ c: "#1a7a3a", l: "Healthy" }, { c: "#c87010", l: "Stress" }, { c: "#b83232", l: "Alert" }].map(s => (
                <div key={s.l} style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 10.5, color: "rgba(255,255,255,0.6)" }}>
                  <div style={{ width: 8, height: 8, borderRadius: 2, background: s.c }} />{s.l}
                </div>
              ))}
            </div>
          </Card>
        </div>
      </div>
    </div>
  );
}

export default FarmMap;
